from docx import Document
from zipfile import ZipFile
from lxml import etree
p='/work/complaint_preparation.docx'; d=Document(p)
for s in ['Title','Heading 1','Heading 2','Normal']:
 st=d.styles[s]; rf=st._element.rPr.rFonts
 print('STYLE',s,{k:rf.get('{http://schemas.openxmlformats.org/wordprocessingml/2006/main}'+k) for k in ['ascii','hAnsi','eastAsia','cs']})
miss=[]
for para in d.paragraphs:
 for r in para.runs:
  if r.text:
   rf=r._element.rPr.rFonts if r._element.rPr is not None else None
   if rf is None or any(rf.get('{http://schemas.openxmlformats.org/wordprocessingml/2006/main}'+k) is None for k in ['ascii','hAnsi','eastAsia','cs']): miss.append(('p',r.text[:30]))
for ti,t in enumerate(d.tables):
 for row in t.rows:
  for c in row.cells:
   for para in c.paragraphs:
    for r in para.runs:
     if r.text:
      rf=r._element.rPr.rFonts if r._element.rPr is not None else None
      if rf is None or any(rf.get('{http://schemas.openxmlformats.org/wordprocessingml/2006/main}'+k) is None for k in ['ascii','hAnsi','eastAsia','cs']): miss.append(('table',r.text[:30]))
print('missing fonts',len(miss),miss[:3])
with ZipFile(p) as z: etree.fromstring(z.read('word/document.xml'))
print('XML parse OK')
